import { escapeHTML, protectHTML, protectCode, restoreHTML, restoreCode, parseAttrs } from './utils.js';
import { renderMath } from './math.js';
import { handleListItem } from './listParser.js';
import { parseTable } from './tableParser.js';

function parseMarkdown(md = '') {
  const lines = md.split('\n');
  const html = [];
  let inCodeBlock = false;
  let codeLang = '';
  const listStack = [];
  let paragraphLines = [];
  let inTable = false;
  let tableRows = [];

  let inMathBlock = false;
  let mathBlockLines = [];

  const footnotes = {};
  const inlineFootnotes = {};

  const flushParagraph = () => {
    if (paragraphLines.length > 0) {
      let text = paragraphLines.join(' ');

      let { text: protectedHtmlText, map: htmlMap } = protectHTML(text);
      let { text: protectedCodeText, map: codeMap } = protectCode(protectedHtmlText);

      let processedText = escapeHTML(protectedCodeText);

      processedText = processedText.replace(/\[\^(.+?)\]\((.+?)\)/g, (_, key, content) => {
        const footnoteKey = key.trim() || `inline-footnote-${Object.keys(inlineFootnotes).length + 1}`;
        inlineFootnotes[footnoteKey] = escapeHTML(content);
        return `<sup id="ref-${footnoteKey}"><a href="#footnote-${footnoteKey}">${footnoteKey}</a></sup>`;
      });

      processedText = processedText
        .replace(/!\[([^\]]*)\]\(([^)]+)\)(?:\{([^}]*)\})?/g, (_, alt, src, attrStr) => {
          const extra = attrStr ? ' ' + parseAttrs(attrStr) : '';
          return `<img alt="${escapeHTML(alt)}" src="${escapeHTML(src)}"${extra} />`;
        })
        .replace(/\[([^\]]+?)\]\(([^)]+)\)/g, (_, linkText, url) => `<a href="${escapeHTML(url)}" target="_blank">${escapeHTML(linkText)}</a>`)
        .replace(/\*\*\*(.+?)\*\*\*/g, '<strong><em>$1</em></strong>')
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        .replace(/\*(.+?)\*/g, '<em>$1</em>')
        .replace(/~~(.+?)~~/g, '<del>$1</del>')
        .replace(/\[\^(.+?)\]/g, (_, key) => `<sup id="ref-${key}"><a href="#footnote-${key}">${key}</a></sup>`);

      processedText = processedText.replace(/(?<!\$)\$(?!\$)(.+?)(?<!\$)\$(?!\$)/g, (_, expr) => renderMath(expr, false));

      processedText = restoreCode(processedText, codeMap);
      processedText = restoreHTML(processedText, htmlMap);

      html.push(`<p>${processedText}</p>`);
      paragraphLines = [];
    }
  };

  const flushList = () => {
    while (listStack.length > 0) {
      const { tag } = listStack.pop();
      html.push(`</${tag}>`);
    }
  };

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i];
    const trimmed = line.trim();

    if (/^```/.test(trimmed)) {
      if (inCodeBlock) {
        html.push(`</code></pre>`);
        inCodeBlock = false;
        codeLang = '';
      } else {
        flushParagraph();
        flushList();
        if (inTable) {
          parseTable(tableRows, html);
          inTable = false;
          tableRows = [];
        }
        inCodeBlock = true;
        codeLang = trimmed.slice(3).trim();
        html.push(`<pre><code class="language-${escapeHTML(codeLang)}">`);
      }
      continue;
    }

    if (inCodeBlock) {
      html.push(escapeHTML(line));
      continue;
    }

    if (trimmed === '$$') {
      if (inMathBlock) {
        const tex = mathBlockLines.join('\n');
        html.push(renderMath(tex, true));
        mathBlockLines = [];
        inMathBlock = false;
      } else {
        flushParagraph();
        flushList();
        inMathBlock = true;
      }
      continue;
    }

    if (inMathBlock) {
      mathBlockLines.push(line);
      continue;
    }

    if (handleListItem(line, listStack, html)) {
      flushParagraph();
      if (inTable) {
        parseTable(tableRows, html);
        inTable = false;
        tableRows = [];
      }
      continue;
    }

    if (/^\|.*\|$/.test(trimmed)) {
      if (!inTable) {
        flushParagraph();
        flushList();
        inTable = true;
      }
      tableRows.push(trimmed);
      continue;
    }

    if (inTable) {
      if (/^\|.*\|$/.test(trimmed)) {
        tableRows.push(trimmed);
        continue;
      } else {
        parseTable(tableRows, html);
        inTable = false;
        tableRows = [];
      }
    }

    if (trimmed === '') {
      flushParagraph();
      flushList();
      continue;
    }

    paragraphLines.push(line);
  }

  flushParagraph();
  flushList();
  if (inTable) {
    parseTable(tableRows, html);
  }

  return html.join('\n');
}

export default parseMarkdown;
